class ListRepo:
    def __init__(self):
        self.items = []

    def add(self, item):
        self.items.append(item)

    def all(self):
        return list(self.items)


class SortedRepo(ListRepo):
    def all(self):
        return sorted(self.items)


class Service:
    def __init__(self):
        self.repo = ListRepo()

    def add(self, value):
        self.repo.add(value)

    def show(self):
        print(self.repo.all())


repo = {"list": ListRepo, "sorted": SortedRepo}[input().strip()]()
service = Service(repo)
for v in (3, 1, 2):
    service.add(v)
service.show()

